#!/bin/bash
# Compiles host/macmosh-host into the macmosh binary: writes Sources/MacMoshKit/Host/HostScriptSource.swift,
# which holds the script's text in a raw string. The same script gives the same bytes.
#
#   scripts/embed-host-script.sh           write the generated file
#   scripts/embed-host-script.sh --check   write nothing; exit 1 if the file is missing or out of date
set -euo pipefail

cd "$(dirname "$0")/.."

script=host/macmosh-host
out=Sources/MacMoshKit/Host/HostScriptSource.swift
me=scripts/embed-host-script.sh

mode='write'
case "${1:-}" in
    "") ;;
    --check) mode='check' ;;
    *)
        echo "usage: $me [--check]" >&2
        exit 2
        ;;
esac

if [ ! -f "$script" ]; then
    echo "$me: $script not found" >&2
    exit 1
fi

# The raw string ends at a closing triple quote followed by #, and \# starts an interpolation.
if grep -qF -e '"""#' "$script"; then
    echo "$me: $script contains \"\"\"# which would end the embedded string early. Change the script." >&2
    exit 1
fi
if grep -qF -e '\#' "$script"; then
    echo "$me: $script contains \\# which Swift reads inside a raw string. Change the script." >&2
    exit 1
fi

generate() {
    printf '%s\n' \
        '// GENERATED by scripts/embed-host-script.sh from host/macmosh-host. Do not edit by hand.' \
        '// After any change to host/macmosh-host, regenerate it with: scripts/embed-host-script.sh' \
        '// (scripts/check.sh fails when this file is out of date.)' \
        '' \
        'enum HostScriptSource {' \
        '    static let text = #"""'
    cat "$script"
    # The newline before the closing delimiter is not part of a Swift multi-line string, so this one
    # keeps the script's own last newline (or adds none when the script has none).
    printf '\n'
    printf '%s\n' \
        '"""#' \
        '}'
}

if [ "$mode" = 'check' ]; then
    if [ ! -f "$out" ]; then
        echo "$me: $out is missing. Run $me to write it." >&2
        exit 1
    fi
    if ! cmp -s <(generate) "$out"; then
        echo "$me: $out is out of date with $script. Run $me to regenerate it." >&2
        exit 1
    fi
    exit 0
fi

mkdir -p "$(dirname "$out")"
generate > "$out"
echo "$me: wrote $out"
